def _install_guards() -> None:
    op.execute("""
        CREATE FUNCTION public.cosmas_guard_vp_clarification_turn()
        RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
        DECLARE
          root record; proposal record; credential record; previous record;
          latest_schedule uuid; latest_proposal uuid;
          response_count integer; event_count integer; latest_sequence integer;
          event_at timestamptz;
        BEGIN
          IF TG_OP = 'UPDATE' THEN
            RAISE EXCEPTION 'Visit Prep patient turns are immutable' USING ERRCODE = '55000';
          END IF;
          IF TG_OP = 'DELETE' THEN
            PERFORM 1 FROM public.visit_prep WHERE id = OLD.visit_prep_id;
            IF FOUND THEN
              RAISE EXCEPTION 'Visit Prep patient turns require aggregate cleanup' USING ERRCODE = '55000';
            END IF;
            RETURN OLD;
          END IF;
          SELECT * INTO root FROM public.visit_prep WHERE id = NEW.visit_prep_id FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'Visit Prep patient turn root does not exist' USING ERRCODE = '23503';
          END IF;
          SELECT * INTO proposal FROM public.visit_prep_clarification_proposal
           WHERE id = NEW.proposal_id AND visit_prep_id = root.id;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'Visit Prep patient turn proposal does not exist' USING ERRCODE = '23503';
          END IF;
          SELECT * INTO credential FROM public.visit_prep_credential_generation
           WHERE visit_prep_id = root.id ORDER BY generation DESC LIMIT 1 FOR UPDATE;
          SELECT id INTO latest_schedule FROM public.visit_prep_schedule_generation
           WHERE visit_prep_id = root.id ORDER BY generation DESC LIMIT 1;
          SELECT COUNT(*) INTO response_count FROM public.visit_prep_question_response WHERE visit_prep_id = root.id;
          SELECT COUNT(*), COALESCE(MAX(event_sequence), 0) INTO event_count, latest_sequence
            FROM public.visit_prep_contribution_event WHERE visit_prep_id = root.id;
          SELECT id INTO latest_proposal FROM public.visit_prep_clarification_proposal
           WHERE visit_prep_id = root.id AND question_id = proposal.question_id
             AND credential_generation = proposal.credential_generation
             AND source_version = proposal.source_version
             AND basis_response_count = proposal.basis_response_count
             AND basis_event_sequence = proposal.basis_event_sequence
           ORDER BY recorded_at DESC, id DESC LIMIT 1;
          event_at := clock_timestamp();
          IF root.lifecycle_state NOT IN ('in_progress', 'completed')
             OR root.confirmed_at IS NULL OR root.confirmed_at > event_at
             OR root.started_at IS NULL OR root.started_at > event_at OR root.revoked_at IS NOT NULL
             OR credential.generation IS NULL OR credential.revoked_at IS NOT NULL
             OR credential.issued_at > event_at OR credential.expires_at <= event_at
             OR latest_schedule IS NULL OR credential.schedule_generation_id <> latest_schedule
             OR proposal.credential_generation <> credential.generation
             OR proposal.actor_role IS DISTINCT FROM root.confirmed_by_role
             OR proposal.owner_practice_member_id <> root.owner_practice_member_id
             OR proposal.question_set_version_id <> root.question_set_version_id
             OR proposal.basis_response_count <> response_count
             OR proposal.basis_event_sequence <> latest_sequence OR event_count <> latest_sequence
             OR proposal.id IS DISTINCT FROM latest_proposal
             OR proposal.recorded_at > event_at THEN
            RAISE EXCEPTION 'Visit Prep patient turn requires current proposal authority' USING ERRCODE = '55000';
          END IF;
          PERFORM 1 FROM public.visit_prep_clarification_decision WHERE proposal_id = proposal.id;
          IF FOUND THEN
            RAISE EXCEPTION 'Visit Prep patient turn proposal is decided' USING ERRCODE = '55000';
          END IF;
          IF proposal.source_turn_id IS NULL THEN
            IF NEW.turn_sequence <> 1 THEN
              RAISE EXCEPTION 'Visit Prep patient turn sequence does not match' USING ERRCODE = '55000';
            END IF;
          ELSE
            SELECT * INTO previous FROM public.visit_prep_clarification_turn
             WHERE id = proposal.source_turn_id AND visit_prep_id = root.id;
            IF NOT FOUND OR previous.turn_sequence <> 1 OR NEW.turn_sequence <> 2
               OR previous.recorded_at > proposal.recorded_at THEN
              RAISE EXCEPTION 'Visit Prep patient turn sequence does not match' USING ERRCODE = '55000';
            END IF;
          END IF;
          NEW.created_at := event_at; NEW.updated_at := event_at; NEW.recorded_at := event_at;
          RETURN NEW;
        END; $$
    """)
