    op.execute("""
        CREATE FUNCTION public.cosmas_guard_vp_clarification_source_turn()
        RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
        DECLARE source_turn record; prior record; latest record;
        BEGIN
          IF NEW.source_turn_id IS NULL THEN RETURN NEW; END IF;
          SELECT * INTO source_turn FROM public.visit_prep_clarification_turn
           WHERE id = NEW.source_turn_id AND visit_prep_id = NEW.visit_prep_id;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'Visit Prep proposal source turn does not exist' USING ERRCODE = '23503';
          END IF;
          SELECT * INTO prior FROM public.visit_prep_clarification_proposal
           WHERE id = source_turn.proposal_id AND visit_prep_id = NEW.visit_prep_id;
          IF NOT FOUND OR prior.question_id <> NEW.question_id
             OR prior.owner_practice_member_id <> NEW.owner_practice_member_id
             OR prior.question_set_version_id <> NEW.question_set_version_id
             OR prior.credential_generation <> NEW.credential_generation
             OR prior.actor_role <> NEW.actor_role OR prior.source_version <> NEW.source_version
             OR prior.basis_response_count <> NEW.basis_response_count
             OR prior.basis_event_sequence <> NEW.basis_event_sequence
             OR prior.source_response_id IS DISTINCT FROM NEW.source_response_id
             OR prior.source_contribution_id IS DISTINCT FROM NEW.source_contribution_id
             OR prior.recorded_at > source_turn.recorded_at
             OR source_turn.recorded_at > clock_timestamp() THEN
            RAISE EXCEPTION 'Visit Prep proposal source turn lineage differs' USING ERRCODE = '23503';
          END IF;
          SELECT * INTO latest FROM public.visit_prep_clarification_proposal
           WHERE visit_prep_id = NEW.visit_prep_id AND question_id = NEW.question_id
             AND credential_generation = NEW.credential_generation AND source_version = NEW.source_version
             AND basis_response_count = NEW.basis_response_count AND basis_event_sequence = NEW.basis_event_sequence
           ORDER BY recorded_at DESC, id DESC LIMIT 1;
          IF latest.id IS DISTINCT FROM prior.id AND latest.source_turn_id IS DISTINCT FROM source_turn.id THEN
            RAISE EXCEPTION 'Visit Prep proposal source turn is superseded' USING ERRCODE = '55000';
          END IF;
          PERFORM 1 FROM public.visit_prep_clarification_decision WHERE proposal_id = latest.id;
          IF FOUND THEN
            RAISE EXCEPTION 'Visit Prep proposal source turn is decided' USING ERRCODE = '55000';
          END IF;
          RETURN NEW;
        END; $$;
        CREATE TRIGGER visit_prep_clarification_proposal_guard_source_turn
        BEFORE INSERT ON public.visit_prep_clarification_proposal
        FOR EACH ROW EXECUTE FUNCTION public.cosmas_guard_vp_clarification_source_turn();
    """)
